import sys

def minion_game(s):
    vowels = set('AEIOU')
    n = len(s)

    kevin_score = 0
    stuart_score = 0

    for i, char in enumerate(s):
        if char in vowels:
            kevin_score += (n - i)
        else:
            stuart_score += (n - i)

    if kevin_score > stuart_score:
        print(f"Kevin {kevin_score}")
    elif stuart_score > kevin_score:
        print(f"Stuart {stuart_score}")
    else:
        print("Draw")

if __name__ == "__main__":
    s = sys.stdin.readline().strip()
    minion_game(s)
